<?php
require_once 'db.php';function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['product_id'],$_POST['price'],$_POST['available'])){$id=(int)$_POST['product_id'];$price=max(0,(float)$_POST['price']);$avail=(int)$_POST['available']?1:0;$st=$conn->prepare("UPDATE products SET price=?,is_available=? WHERE product_id=?");$st->bind_param('dii',$price,$avail,$id);$st->execute();$st->close();$notice='Product updated.';}
$products=$conn->query("SELECT p.product_id,p.product_name,p.price,p.is_available,c.category_name FROM products p JOIN categories c ON c.category_id=p.category_id ORDER BY c.category_id,p.product_name");
$summary=$conn->query("SELECT COUNT(*) orders_count,COALESCE(SUM(CASE WHEN payment_status='Paid' THEN total_amount ELSE 0 END),0) paid_sales,COALESCE(SUM(CASE WHEN order_status='Pending' THEN 1 ELSE 0 END),0) pending_count FROM orders")->fetch_assoc();
$low=$conn->query("SELECT p.product_name,i.stock_quantity,i.reorder_level FROM inventory i JOIN products p ON p.product_id=i.product_id WHERE i.stock_quantity<=i.reorder_level ORDER BY i.stock_quantity LIMIT 10");
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin | Brew Eua's</title><link rel="stylesheet" href="kiosk.css"></head><body><header class="top"><a class="brand" href="index.php"><img src="logo.jpg" alt="Logo"><span>Brew Eua's<small>BREW & BITES</small></span></a><nav class="nav"><a href="index.php">Home</a><a href="menu.php">Menu</a><a href="order.php">Checkout</a><a href="staff.php">Staff</a><a class="active" href="admin.php">Admin</a></nav></header><main class="wrap"><h1 class="section-title">Admin dashboard</h1><p class="muted">Demo admin screen. Add authentication before exposing this page to customers or the internet.</p><div class="grid"><div class="panel"><div class="muted">All orders</div><div class="total"><?= (int)$summary['orders_count'] ?></div></div><div class="panel"><div class="muted">Pending orders</div><div class="total"><?= (int)$summary['pending_count'] ?></div></div><div class="panel"><div class="muted">Paid sales</div><div class="total">₱<?= number_format((float)$summary['paid_sales'],2) ?></div><div class="small">Only orders marked Paid are counted.</div></div></div><?php if($notice): ?><div class="success"><?= esc($notice) ?></div><?php endif ?><h2 class="section-title">Manage products</h2><div class="panel table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Availability</th><th>Save</th></tr></thead><tbody><?php if($products) while($p=$products->fetch_assoc()): ?><tr><form method="post"><td><?= esc($p['product_name']) ?><input type="hidden" name="product_id" value="<?= (int)$p['product_id'] ?>"></td><td><?= esc($p['category_name']) ?></td><td><input type="number" name="price" min="0" step=".01" value="<?= esc($p['price']) ?>" style="width:110px"></td><td><select name="available"><option value="1" <?= $p['is_available']?'selected':'' ?>>Available</option><option value="0" <?= !$p['is_available']?'selected':'' ?>>Unavailable</option></select></td><td><button class="btn" type="submit">Save</button></td></form></tr><?php endwhile ?></tbody></table></div><h2 class="section-title">Low stock alert</h2><div class="panel table-wrap"><table><thead><tr><th>Product</th><th>Stock</th><th>Reorder level</th></tr></thead><tbody><?php if($low) while($r=$low->fetch_assoc()): ?><tr><td><?= esc($r['product_name']) ?></td><td><?= (int)$r['stock_quantity'] ?></td><td><?= (int)$r['reorder_level'] ?></td></tr><?php endwhile ?></tbody></table><p class="small">Your current backup has inventory quantities set to 0, so these products will appear as low stock until you update inventory.</p></div></main></body></html>